[{"order":1,"type":"heading","text":"Doubly Linked Lists: Insertion, Deletion, Traversal"},{"order":2,"type":"paragraph","text":"A doubly linked list is a linear data structure where each node contains data and pointers to both the next and previous nodes in the sequence. This bidirectional linking allows for efficient traversal in both directions, which is a key advantage over singly linked lists."},{"order":3,"type":"subheading","text":"Node Structure"},{"order":4,"type":"paragraph","text":"Each node in a doubly linked list typically consists of three parts:"},{"order":5,"type":"bullet_point","text":"Data: The actual data stored in the node."},{"order":6,"type":"bullet_point","text":"Next: A pointer to the next node in the list."},{"order":7,"type":"bullet_point","text":"Prev: A pointer to the previous node in the list."},{"order":8,"type":"subheading","text":"Insertion"},{"order":9,"type":"paragraph","text":"Insertion in a doubly linked list involves creating a new node and updating the pointers of the surrounding nodes. There are three common insertion scenarios:"},{"order":10,"type":"bullet_point","text":"Insertion at the beginning."},{"order":11,"type":"bullet_point","text":"Insertion at the end."},{"order":12,"type":"bullet_point","text":"Insertion at a specific position."},{"order":13,"type":"subheading","text":"Insertion at the Beginning"},{"order":14,"type":"paragraph","text":"To insert a new node at the beginning:"},{"order":15,"type":"paragraph","text":"1. Create a new node with the desired data."},{"order":16,"type":"paragraph","text":"2. Set the 'next' pointer of the new node to the current head of the list."},{"order":17,"type":"paragraph","text":"3. Set the 'prev' pointer of the new node to NULL (as it's the new head)."},{"order":18,"type":"paragraph","text":"4. If the list was not empty, set the 'prev' pointer of the original head node to the new node."},{"order":19,"type":"paragraph","text":"5. Update the head of the list to point to the new node."},{"order":20,"type":"code","text":"function insertAtBeginning(data) {
  const newNode = { data: data, next: null, prev: null };
  if (!head) {
    head = newNode;
    return;
  }
  newNode.next = head;
  head.prev = newNode;
  head = newNode;
}"},{"order":21,"type":"subheading","text":"Insertion at the End"},{"order":22,"type":"paragraph","text":"To insert a new node at the end:"},{"order":23,"type":"paragraph","text":"1. Create a new node with the desired data."},{"order":24,"type":"paragraph","text":"2. Set the 'next' pointer of the new node to NULL (as it's the new tail)."},{"order":25,"type":"paragraph","text":"3. If the list is empty, set the head to the new node and the 'prev' pointer of the new node to NULL. Return."},{"order":26,"type":"paragraph","text":"4. Traverse to the last node in the list."},{"order":27,"type":"paragraph","text":"5. Set the 'next' pointer of the last node to the new node."},{"order":28,"type":"paragraph","text":"6. Set the 'prev' pointer of the new node to the last node."},{"order":29,"type":"code","text":"function insertAtEnd(data) {
  const newNode = { data: data, next: null, prev: null };
  if (!head) {
    head = newNode;
    return;
  }
  let current = head;
  while (current.next) {
    current = current.next;
  }
  current.next = newNode;
  newNode.prev = current;
}"},{"order":30,"type":"subheading","text":"Insertion at a Specific Position"},{"order":31,"type":"paragraph","text":"To insert a new node at a specific position (index):"},{"order":32,"type":"paragraph","text":"1. Create a new node with the desired data."},{"order":33,"type":"paragraph","text":"2. Traverse to the node at the position immediately before the desired insertion point."},{"order":34,"type":"paragraph","text":"3. Update the 'next' and 'prev' pointers of the surrounding nodes and the new node to maintain the list's integrity."},{"order":35,"type":"code","text":"function insertAtPosition(data, position) {
  if (position < 0) return;
  const newNode = { data: data, next: null, prev: null };
  if (position === 0) {
    newNode.next = head;
    if (head) head.prev = newNode;
    head = newNode;
    return;
  }
  let current = head;
  let i = 0;
  while (current && i < position - 1) {
    current = current.next;
    i++;
  }
  if (!current) return; // Position out of bounds
  newNode.next = current.next;
  if (current.next) current.next.prev = newNode;
  current.next = newNode;
  newNode.prev = current;
}"},{"order":36,"type":"subheading","text":"Deletion"},{"order":37,"type":"paragraph","text":"Deletion in a doubly linked list also involves updating pointers. Similar to insertion, there are different scenarios:"},{"order":38,"type":"bullet_point","text":"Deletion from the beginning."},{"order":39,"type":"bullet_point","text":"Deletion from the end."},{"order":40,"type":"bullet_point","text":"Deletion from a specific position."},{"order":41,"type":"subheading","text":"Deletion from the Beginning"},{"order":42,"type":"paragraph","text":"To delete the first node:"},{"order":43,"type":"paragraph","text":"1. If the list is empty, there is nothing to delete. Return."},{"order":44,"type":"paragraph","text":"2. Update the head to point to the second node in the list."},{"order":45,"type":"paragraph","text":"3. If the list had more than one node, set the 'prev' pointer of the new head to NULL."},{"order":46,"type":"code","text":"function deleteFromBeginning() {
  if (!head) return;
  head = head.next;
  if (head) head.prev = null;
}"},{"order":47,"type":"subheading","text":"Deletion from the End"},{"order":48,"type":"paragraph","text":"To delete the last node:"},{"order":49,"type":"paragraph","text":"1. If the list is empty, there is nothing to delete. Return."},{"order":50,"type":"paragraph","text":"2. If the list has only one node, set the head to NULL. Return."},{"order":51,"type":"paragraph","text":"3. Traverse to the second-to-last node in the list."},{"order":52,"type":"paragraph","text":"4. Set the 'next' pointer of the second-to-last node to NULL."},{"order":53,"type":"code","text":"function deleteFromEnd() {
  if (!head) return;
  if (!head.next) {
    head = null;
    return;
  }
  let current = head;
  while (current.next.next) {
    current = current.next;
  }
  current.next = null;
}"},{"order":54,"type":"subheading","text":"Deletion from a Specific Position"},{"order":55,"type":"paragraph","text":"To delete a node from a specific position (index):"},{"order":56,"type":"paragraph","text":"1. If the position is invalid (e.g., negative or out of bounds), return."},{"order":57,"type":"paragraph","text":"2. Traverse to the node at the specified position."},{"order":58,"type":"paragraph","text":"3. Update the 'next' and 'prev' pointers of the surrounding nodes to bypass the node being deleted."},{"order":59,"type":"code","text":"function deleteFromPosition(position) {
  if (!head || position < 0) return;
  if (position === 0) {
    head = head.next;
    if (head) head.prev = null;
    return;
  }
  let current = head;
  let i = 0;
  while (current && i < position) {
    current = current.next;
    i++;
  }
  if (!current) return; // Position out of bounds
  if (current.prev) current.prev.next = current.next;
  if (current.next) current.next.prev = current.prev;
}"},{"order":60,"type":"subheading","text":"Traversal"},{"order":61,"type":"paragraph","text":"Traversal in a doubly linked list can be done in two directions:"},{"order":62,"type":"bullet_point","text":"Forward Traversal: Starting from the head and moving towards the tail using the 'next' pointers."},{"order":63,"type":"bullet_point","text":"Backward Traversal: Starting from the tail (if known) and moving towards the head using the 'prev' pointers."},{"order":64,"type":"subheading","text":"Forward Traversal Implementation"},{"order":65,"type":"code","text":"function traverseForward() {
  let current = head;
  while (current) {
    console.log(current.data);
    current = current.next;
  }
}"},{"order":66,"type":"subheading","text":"Backward Traversal Implementation"},{"order":67,"type":"code","text":"function traverseBackward(tail) { // Assuming you have a reference to the tail
  let current = tail;
  while (current) {
    console.log(current.data);
    current = current.prev;
  }
}"}]
